import{R as e,a as n}from"./chunks/ResearchPapers.0fMEDK10.js";import{o as i,c as o,j as r,a as t,E as l,a0 as s}from"./chunks/framework.BXmxXpv-.js";const p={class:"research-page"},f=JSON.parse('{"title":"研究方向","description":"从微计算、微通信和能量管理到复杂感知，研究如何以可负担的成本持续获取真实世界的有效信息。","frontmatter":{"title":"研究方向","description":"从微计算、微通信和能量管理到复杂感知，研究如何以可负担的成本持续获取真实世界的有效信息。","aside":false},"headers":[],"relativePath":"zh/research.md","filePath":"zh/research.md","lastUpdated":1793675049000}'),d={name:"zh/research.md"},S=Object.assign(d,{setup(u){return(g,a)=>(i(),o("div",null,[r("div",p,[a[0]||(a[0]=r("h1",{id:"研究方向",tabindex:"-1"},[t("研究方向 "),r("a",{class:"header-anchor",href:"#研究方向","aria-label":'Permalink to "研究方向"'},"​")],-1)),a[1]||(a[1]=r("p",null,"从一次温度采样到一段声音、一幅图像，我们研究完成感知任务究竟需要哪些计算、通信与运行支撑，让有限的硬件和能量获得更多有用的信息。",-1)),a[2]||(a[2]=r("h2",{id:"研究目标",tabindex:"-1"},[t("研究目标 "),r("a",{class:"header-anchor",href:"#研究目标","aria-label":'Permalink to "研究目标"'},"​")],-1)),a[3]||(a[3]=r("p",null,"我们希望让感知网络以更低的成本覆盖更广的世界，持续获取人类生活、生产与自然环境中的有效信息，帮助人们理解环境、预判变化，并据此作出决策、采取行动。",-1)),a[4]||(a[4]=r("p",null,"大规模部署要求终端便宜、节能、易维护，也要求信息可靠、反馈及时。我们的研究从端侧出发，结合边缘与云端的资源，重新安排功能的执行位置、实现方式和操作粒度，降低获取单位有效信息的综合成本。",-1)),l(e,{lang:"zh"}),a[5]||(a[5]=s('<h2 id="微计算" tabindex="-1">微计算 <a class="header-anchor" href="#微计算" aria-label="Permalink to &quot;微计算&quot;">​</a></h2><p><strong>让轻量、重复的感知任务用更直接的路径执行。</strong> 读取寄存器、周期采样和简单处理所需的工作量很小，但逐节点配置的通用控制、器件适配与无线交互仍可能带来较高开销。我们研究如何保留必要的本地能力，同时把适合共享的支撑交给网关或邻近节点。</p><ul><li><strong>直接连接器件。</strong> 通过射频到总线转换，将无线信令接入外设操作。</li><li><strong>分离适配与执行。</strong> 用可组合的操作描述不同器件，由配置连接任务与端侧硬件。</li><li><strong>选择执行粒度。</strong> 连续操作在本地完成，处理器由邻近节点共享，减少重复控制与无线往返。</li></ul><p>这些工作分别回答接口如何连接、器件如何适配、任务在哪里执行等问题，共同构成面向轻量感知的架构选择。</p>',4)),l(n,{topic:"computing",lang:"zh"}),a[6]||(a[6]=r("h2",{id:"微通信",tabindex:"-1"},[t("微通信 "),r("a",{class:"header-anchor",href:"#微通信","aria-label":'Permalink to "微通信"'},"​")],-1)),a[7]||(a[7]=r("p",null,[r("strong",null,"让终端以更少的电路与处理开销完成无线收发。"),t(" 除了传输数据，终端还要承担参考生成、同步、采样、解扩和解调。我们利用基础设施与终端的资源差异，通过协同参考信号和模拟、混合信号电路，改变这些通信操作的实现路径。")],-1)),a[8]||(a[8]=r("p",null,"从 Passive DSSS 的抗干扰下行，到 μMote 的无源 chirp 解扩，再到 Sisyphus 的 LoRa 接收处理，研究重点始终是把通信能力落实为终端可承担的信号处理过程，并结合覆盖、速率、可靠性与基础设施要求选择方案。",-1)),l(n,{topic:"communication",lang:"zh"}),a[9]||(a[9]=r("h2",{id:"能量管理",tabindex:"-1"},[t("能量管理 "),r("a",{class:"header-anchor",href:"#能量管理","aria-label":'Permalink to "能量管理"'},"​")],-1)),a[10]||(a[10]=r("p",null,[r("strong",null,"让稀缺能量更多地用于完成任务。"),t(" 无电池终端从环境中获取能量，供能随时间变化；监测储能、判断何时运行，本身也会消耗能量。我们将能量状态感知、管理计算和任务启动一起设计，研究网关协同管理与端侧硬件准入两条路径。")],-1)),a[11]||(a[11]=r("p",null,"μMan 关注管理工作由谁承担，Hades 关注任务启动条件如何由硬件直接判断。二者从不同层面减少管理开销，使任务执行与供能条件相匹配。",-1)),l(n,{topic:"energy",lang:"zh"}),a[12]||(a[12]=s('<h2 id="复杂感知" tabindex="-1">复杂感知 <a class="header-anchor" href="#复杂感知" aria-label="Permalink to &quot;复杂感知&quot;">​</a></h2><p class="research-status">正在探索 · 从基础物理量走向音频、图像与视频</p><p><strong>在信息产生的早期，确定任务需要保留什么、处理什么、传输什么。</strong> 音视频带来更丰富的环境信息，也增加采样、存储、计算和传输压力。我们将前端信息组织与端侧执行相结合，探索三类相互配合的工作：</p><ul><li><strong>音频与事件驱动处理。</strong> 探索脉冲神经网络（SNN）与能量控制的配合，按事件和任务需求组织连续信号处理。</li><li><strong>视觉结构与任务证据。</strong> Sensor-to-Semantics（S2S）研究图元、局部结构及其关系的表达，让后端按需使用证据，并在信息不足时补充图像或局部区域。</li><li><strong>可配置计算与数据通路。</strong> 让规则、重复的前端处理匹配简化计算阵列和专用可重构执行，协同减少控制与数据搬运开销。</li></ul><p>这一方向以任务效果检验信息取舍，并考察前端处理是否实际减少了后续计算与传输。以下已发表工作分别展示了可配置执行与按需视觉采样的研究基础和应用实例。</p>',5)),l(n,{topic:"sensing",lang:"zh"}),a[13]||(a[13]=r("h2",{id:"安全与信息应用",tabindex:"-1"},[t("安全与信息应用 "),r("a",{class:"header-anchor",href:"#安全与信息应用","aria-label":'Permalink to "安全与信息应用"'},"​")],-1)),a[14]||(a[14]=r("p",null,"感知信息要进入实际系统，还需要可信的采集与交互，以及高效的数据分析。实验室同时研究无线与物理感知中的隐私防护、用户认证，以及流式图计算、推荐和多源信息处理，将系统方法用于可穿戴设备、环境监测和数据驱动应用。",-1)),l(n,{topic:"applications",lang:"zh"}),a[15]||(a[15]=r("p",null,"我们围绕具体场景检验信息质量、响应时间、能量消耗与部署代价，使器件、通信、计算和应用的改进共同服务于持续、可靠的感知。",-1)),a[16]||(a[16]=r("p",null,[r("a",{href:"/zh/publication"},"全部精选论文"),t(" · "),r("a",{href:"/zh/projects"},"代表性科研项目"),t(" · "),r("a",{href:"/zh/contact"},"联系我们")],-1))])]))}});export{f as __pageData,S as default};
